package org.telegram.ui;

import android.content.Context;
import android.view.*;
import android.widget.*;
import org.json.JSONObject;
import org.telegram.messenger.*;
import org.telegram.ui.ActionBar.*;
import org.telegram.ui.Components.*;
import org.telegram.ui.Cells.TextSettingsCell;
import android.os.Bundle;

/** Shared pixel canvas tools; all writes use authenticated, replay-safe row mutations. */
public final class DevGramPixelCanvasActivity extends BaseFragment {
    private final long owner,viewer;private final JSONObject row;private DevGramPixelCanvasView canvas;private boolean grid=true;private TextView draftStatus,sendButton,shopStatus;private TextSettingsCell capacityBuy,refillBuy;
    private DevGramCanvasOverlayEditor overlay;private LinearLayout colorChoices;private android.graphics.Bitmap paletteBitmap;private boolean paletteInitialized;
    private final java.util.HashMap<Integer,TextView> swatches=new java.util.HashMap<>();private int remainingGeneration;
    private final Runnable remaining=()->{if(canvas==null||canvas.overlay()==null)return;int request=remainingGeneration;canvas.remaining(counts->{if(request!=remainingGeneration)return;for(java.util.Map.Entry<Integer,TextView> entry:swatches.entrySet()){Integer count=counts.get(entry.getKey());TextView swatch=entry.getValue();swatch.setText(count==null?(entry.getKey()==0?"×":""):Integer.toString(count));if(count!=null)swatch.setContentDescription(String.format("#%08X",entry.getKey())+" · "+t("Осталось пикселей")+": "+count);}});};
    private final Runnable policy=this::accessChanged;
    private void accessChanged(){if(getUserConfig().getClientUserId()!=viewer||!DevGramProfileCustomization.enabled()||!DevGramProfilePolicy.allowed(owner,"profile.blocks.pixels")||!DevGramProfilePolicy.allowed(owner,"profile.blocks"))DevGramAccessNavigation.close(this);}
    public DevGramPixelCanvasActivity(int account,long owner,JSONObject row){currentAccount=account;this.owner=owner;viewer=UserConfig.getInstance(account).getClientUserId();this.row=DevGramProfileDocument.copy(row);}
    private String t(String text){return DevGramLocale.text(text);}
    @Override public View createView(Context context){actionBar.setTitle(row.optString("title").isEmpty()?t("Пиксельное полотно"):row.optString("title"));actionBar.setBackButtonImage(R.drawable.ic_ab_back);actionBar.setActionBarMenuOnItemClick(new ActionBar.ActionBarMenuOnItemClick(){public void onItemClick(int id){if(id==-1)finishFragment();}});
        LinearLayout content=DevGramStudioControls.column(context);canvas=new DevGramPixelCanvasView(context,currentAccount,owner,row,resourceProvider,false);content.addView(canvas,new LinearLayout.LayoutParams(-1,0,1));overlay=new DevGramCanvasOverlayEditor(this,canvas,owner,viewer,row.optString("id"),resourceProvider);
        LinearLayout draftBar=new LinearLayout(context);draftBar.setGravity(Gravity.CENTER_VERTICAL);draftBar.setPadding(AndroidUtilities.dp(16),AndroidUtilities.dp(8),AndroidUtilities.dp(16),AndroidUtilities.dp(8));draftStatus=DevGramStudioControls.text(context,"",12,false,resourceProvider);draftStatus.setMaxLines(2);draftBar.addView(draftStatus,new LinearLayout.LayoutParams(0,-2,1));sendButton=DevGramStudioControls.text(context,"Отправить",14,true,resourceProvider);sendButton.setGravity(Gravity.CENTER);sendButton.setPadding(AndroidUtilities.dp(18),AndroidUtilities.dp(12),AndroidUtilities.dp(18),AndroidUtilities.dp(12));sendButton.setTextColor(Theme.getColor(Theme.key_featuredStickers_buttonText,resourceProvider));sendButton.setBackground(DevGramStudioControls.surface(Theme.getColor(Theme.key_featuredStickers_addButton,resourceProvider),0));sendButton.setOnClickListener(v->canvas.send());draftBar.addView(sendButton);content.addView(draftBar);canvas.onDraftChanged(this::updateDraftStatus);canvas.onInspected(this::inspect);updateDraftStatus();
        HorizontalScrollView palette=new HorizontalScrollView(context);colorChoices=new LinearLayout(context);palette.addView(colorChoices);content.addView(palette,new LinearLayout.LayoutParams(-1,-2));updatePalette();
        HorizontalScrollView tools=new HorizontalScrollView(context);LinearLayout buttons=new LinearLayout(context);String[] labels={"Отменить действие","Вернуть действие","Кисть","Рука","Ластик","Пипетка","Сетка","Показать начало","Цвет","Размер кисти","Стереть черновик","О пикселе","Магазин","Подложка для рисования"};int[] icons={R.drawable.iv_undo,R.drawable.iv_redo,R.drawable.photo_paint_brush,R.drawable.menu_feature_hands,R.drawable.msg_delete,R.drawable.msg_palette,R.drawable.msg_photo_crop,R.drawable.msg_location,R.drawable.msg_theme,R.drawable.msg_edit,R.drawable.msg_delete_filled,R.drawable.msg_info,R.drawable.msg_payment_card,R.drawable.msg_photos};for(int i=0;i<labels.length;i++){int op=i;ImageView button=new ImageView(context);button.setImageResource(icons[i]);button.setScaleType(ImageView.ScaleType.CENTER);button.setColorFilter(Theme.getColor(Theme.key_windowBackgroundWhiteGrayIcon,resourceProvider));button.setContentDescription(t(labels[i]));if(android.os.Build.VERSION.SDK_INT>=26)button.setTooltipText(t(labels[i]));button.setBackground(Theme.createSelectorDrawable(Theme.getColor(Theme.key_listSelector,resourceProvider),2));button.setOnClickListener(v->{if(op<2)canvas.history(op==1);else if(op<6)canvas.tool(op-2);else if(op==6)canvas.grid(grid=!grid);else if(op==7)canvas.resetView();else if(op==8)color();else if(op==9)brush();else if(op==10)canvas.clearDraft();else if(op==11)canvas.tool(4);else if(op==12)shop();else overlay.show();});buttons.addView(button,new LinearLayout.LayoutParams(AndroidUtilities.dp(48),AndroidUtilities.dp(48)));}tools.addView(buttons);content.addView(tools);
        if(getUserConfig().getClientUserId()==DevGramCommunityProfiles.owner(owner)){TextView clear=DevGramStudioControls.text(context,"Очистить полотно",14,false,resourceProvider);clear.setGravity(Gravity.CENTER);clear.setPadding(0,AndroidUtilities.dp(12),0,AndroidUtilities.dp(12));clear.setTextColor(Theme.getColor(Theme.key_text_RedRegular,resourceProvider));clear.setOnClickListener(v->new AlertDialog.Builder(getParentActivity(),resourceProvider).setTitle(t("Очистить полотно?")).setMessage(t("Рисунки всех посетителей будут удалены." )).setPositiveButton(t("Очистить"),(d,w)->canvas.clear()).setNegativeButton(DevGramLocale.getString(R.string.Cancel),null).show());content.addView(clear);}
        FrameLayout root=new FrameLayout(context);root.setBackgroundColor(Theme.getColor(Theme.key_windowBackgroundWhite,resourceProvider));content.setPadding(0,AndroidUtilities.statusBarHeight+ActionBar.getCurrentActionBarHeight(),0,AndroidUtilities.navigationBarHeight);root.addView(content,new FrameLayout.LayoutParams(-1,-1));actionBar.setAddToContainer(false);root.addView(actionBar,LayoutHelper.createFrame(-1,-2,Gravity.TOP));if(android.os.Build.VERSION.SDK_INT>=30)root.setOnApplyWindowInsetsListener((v,insets)->{content.setPadding(0,insets.getInsets(android.view.WindowInsets.Type.systemBars()).top+ActionBar.getCurrentActionBarHeight(),0,insets.getInsets(android.view.WindowInsets.Type.systemBars()).bottom);return insets;});fragmentView=root;DevGramProfilePolicy.listen(policy);return fragmentView;
    }
    private void updateDraftStatus(){if(canvas==null||draftStatus==null)return;updatePalette();remainingGeneration++;if(colorChoices!=null){colorChoices.removeCallbacks(remaining);if(canvas.overlay()!=null)colorChoices.postDelayed(remaining,200);}draftStatus.setText((canvas.canPaint()?t("Пиксели")+": "+canvas.ready()+"/"+canvas.player().optInt("max",30):canvas.status())+" · "+t("Черновик")+": "+canvas.draftSize());sendButton.setText(t(canvas.sending()?"Отправляю…":"Отправить"));sendButton.setEnabled(canvas.canPaint()&&canvas.draftSize()>0&&!canvas.sending());sendButton.setAlpha(sendButton.isEnabled()?1:.5f);updateShop();}
    private void updatePalette(){if(canvas==null||colorChoices==null)return;DevGramCanvasOverlay overlay=canvas.overlay();android.graphics.Bitmap pixels=overlay==null?null:overlay.pixels;if(paletteInitialized&&pixels==paletteBitmap)return;paletteInitialized=true;paletteBitmap=pixels;colorChoices.removeAllViews();swatches.clear();java.util.LinkedHashSet<Integer> colors=new java.util.LinkedHashSet<>();for(int color:DevGramRowStateController.PALETTE)colors.add(color);if(overlay!=null)for(int color:overlay.palette())colors.add(color);for(int color:colors){TextView swatch=new TextView(colorChoices.getContext());swatch.setGravity(Gravity.CENTER);swatch.setTextSize(9);swatch.setTextColor(color==0?Theme.getColor(Theme.key_windowBackgroundWhiteBlackText,resourceProvider):androidx.core.graphics.ColorUtils.calculateLuminance(color)>.45?android.graphics.Color.BLACK:android.graphics.Color.WHITE);swatch.setText(color==0?"×":"");swatch.setContentDescription(color==0?t("Пустой цвет"):String.format("#%08X",color));swatch.setBackground(Theme.createRoundRectDrawable(AndroidUtilities.dp(8),color==0?Theme.getColor(Theme.key_windowBackgroundGray,resourceProvider):color));swatch.setOnClickListener(v->canvas.color(color));LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(AndroidUtilities.dp(36),AndroidUtilities.dp(36));params.setMargins(AndroidUtilities.dp(4),AndroidUtilities.dp(8),AndroidUtilities.dp(4),AndroidUtilities.dp(8));colorChoices.addView(swatch,params);swatches.put(color,swatch);}}
    private void shop(){
        Context context=getParentActivity();LinearLayout body=DevGramStudioControls.column(context);shopStatus=DevGramStudioControls.text(context,"",15,false,resourceProvider);shopStatus.setPadding(AndroidUtilities.dp(22),AndroidUtilities.dp(18),AndroidUtilities.dp(22),AndroidUtilities.dp(18));body.addView(shopStatus);
        capacityBuy=new TextSettingsCell(context,resourceProvider);refillBuy=new TextSettingsCell(context,resourceProvider);body.addView(capacityBuy);body.addView(refillBuy);capacityBuy.setOnClickListener(v->canvas.buy("max5"));refillBuy.setOnClickListener(v->canvas.buy("refill30"));
        TextView hint=DevGramStudioControls.text(context,"Пиксели восстанавливаются со временем. За новый уровень начисляются монеты для улучшений.",13,false,resourceProvider);hint.setPadding(AndroidUtilities.dp(22),AndroidUtilities.dp(18),AndroidUtilities.dp(22),AndroidUtilities.dp(24));hint.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText,resourceProvider));body.addView(hint);updateShop();BottomSheet sheet=new BottomSheet.Builder(context,false,resourceProvider).setTitle(t("Магазин пикселей")).setCustomView(body).create();sheet.fixNavigationBarKey(Theme.key_dialogBackground);showDialog(sheet,d->{shopStatus=null;capacityBuy=null;refillBuy=null;});
    }
    private void updateShop(){if(shopStatus==null||canvas==null)return;JSONObject player=canvas.player(),prices=player.optJSONObject("shop");int coins=player.optInt("drops"),max=player.optInt("max",30),upgrade=prices==null?350:prices.optInt("max5",350),refill=prices==null?350:prices.optInt("refill30",350);shopStatus.setText(t("Уровень")+" "+player.optInt("level",1)+" · "+player.optInt("xp")+"/"+player.optInt("need",30)+" XP\n"+t("Монеты")+": "+coins+"\n"+t("Пиксели")+": "+canvas.ready()+"/"+max+" · "+t("Нарисовано")+": "+player.optLong("dots"));capacityBuy.setTextAndValue(t("Увеличить запас на 5"),Integer.toString(upgrade),true);refillBuy.setTextAndValue(t("Пополнить на 30 пикселей"),Integer.toString(refill),true);capacityBuy.setEnabled(!canvas.sending()&&coins>=upgrade&&max<500);refillBuy.setEnabled(!canvas.sending()&&coins>=refill&&canvas.ready()<max);capacityBuy.setAlpha(capacityBuy.isEnabled()?1:.5f);refillBuy.setAlpha(refillBuy.isEnabled()?1:.5f);}
    private void inspect(JSONObject result){
        if(getParentActivity()==null)return;JSONObject cell=result.optJSONObject("cell");int x=result.optInt("x"),y=result.optInt("y");TextSettingsCell copy=pixelLink(x,y);if(cell==null){showDialog(new AlertDialog.Builder(getParentActivity(),resourceProvider).setTitle(t("Пустой пиксель")).setMessage(x+", "+y).setView(copy).setPositiveButton(t("Закрыть"),null).create());return;}
        long author=cell.optLong("actor");boolean banned=cell.optBoolean("banned");String info=t("Автор")+": "+author+"\n"+t("Координаты")+": "+x+", "+y+"\n"+String.format("#%06X",cell.optLong("color")&0xffffff)+"\n"+java.text.DateFormat.getDateTimeInstance().format(new java.util.Date(cell.optLong("at")*1000));AlertDialog.Builder dialog=new AlertDialog.Builder(getParentActivity(),resourceProvider).setTitle(t("О пикселе")).setMessage(info).setView(copy).setPositiveButton(t("Профиль автора"),(d,w)->{Bundle args=new Bundle();args.putLong("user_id",author);presentFragment(new ProfileActivity(args));}).setNegativeButton(t("Закрыть"),null);if(viewer==DevGramCommunityProfiles.owner(owner)&&author!=owner)dialog.setNeutralButton(t(banned?"Разрешить рисование":"Запретить рисование"),(d,w)->canvas.ban(author,!banned));showDialog(dialog.create());
    }
    private TextSettingsCell pixelLink(int x,int y){TextSettingsCell copy=new TextSettingsCell(getParentActivity(),resourceProvider);copy.setText(t("Копировать ссылку на пиксель"),false);copy.setOnClickListener(v->{AndroidUtilities.addToClipboard(DevGramCanvasLink.build(owner,row.optString("id"),x,y));BulletinFactory.of(this).createCopyLinkBulletin().show();});return copy;}
    private void color(){DevGramColorPickerView picker=new DevGramColorPickerView(getParentActivity(),resourceProvider,true);picker.setColor(canvas.color());final int[] selected={canvas.color()};picker.setListener(value->selected[0]=value);new AlertDialog.Builder(getParentActivity(),resourceProvider).setTitle(t("Цвет")).setView(picker).setPositiveButton(t("Применить"),(d,w)->canvas.color(selected[0])).setNegativeButton(DevGramLocale.getString(R.string.Cancel),null).show();}
    private void brush(){new AlertDialog.Builder(getParentActivity(),resourceProvider).setTitle(t("Размер кисти")).setItems(new String[]{"1 px","2 px","3 px","4 px","6 px","8 px"},(d,which)->canvas.brush(new int[]{1,2,3,4,6,8}[which])).show();}
    @Override public void onActivityResultFragment(int request,int result,android.content.Intent data){super.onActivityResultFragment(request,result,data);if(overlay!=null)overlay.result(request,result,data);}
    @Override public void onFragmentDestroy(){remainingGeneration++;if(colorChoices!=null)colorChoices.removeCallbacks(remaining);DevGramProfilePolicy.unlisten(policy);if(overlay!=null)overlay.close();if(canvas!=null){canvas.onDraftChanged(null);canvas.onInspected(null);}super.onFragmentDestroy();}
}
